window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-194ea1174fb3e714"]={"versions": [{"id": "FIG-194ea1174fb3e714", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Teilschritts „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P04mProtect()</code> des AUTOSAR E2E-Profils 4m (<code>AUTOSAR_PRS_E2EProtocol</code>). Es beschreibt die serialisierende Einbettung des Sequenzzählers in das zu übertragende Datenfeld.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext:</strong> Aufrufkontext <code>E2E_P04mProtect()</code> (gekennzeichnet über das Aktivitätsknoten-Symbol oben links).\n</li><li><strong>Zustandsstruktur / Entität:</strong> <code>State-&gt;Counter</code> (2-Byte-Zählerwert aus dem Zustandsvektor des Senders).\n</li><li><strong>Zielpuffer / Datenschnittstelle:</strong> Byte-Array <code>Data[]</code> an den Indexpositionen <code>[Offset+2...Offset+3]</code>.\n</li><li><strong>Format / Byte-Order:</strong> Big-Endian-Serialisierung (Most Significant Byte zuerst).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Pseudozustand:</strong> Start des Teilschritts „Write Counter“.\n</li><li><strong>Aktionszustand:</strong> Ausführung der Operation „Copy 2-byte State-&gt;Counter on bytes Data[Offset+2...Offset+3] in Big Endian order“. Hierbei wird der 16-Bit-Zählerwert des aktuellen Übertragungszustands big-endian in zwei aufeinanderfolgende Bytes ab Adresse <code>Offset+2</code> kopiert.\n</li><li><strong>Aktivitätsendzustand:</strong> Abschluss der Aktivität und Übergang zum nachfolgenden Schritt des E2E-Profils 4m Protect-Ablaufs.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00760]</code>. Entwickler von E2E-Profil-4m-Treibern müssen sicherstellen, dass das Feld <code>Counter</code> der Sender-Zustandsstruktur vor der Prüfsummenberechnung exakt an Offset-Position 2 und 3 im Nutzdaten-Puffer in Netzwerk-Byte-Reihenfolge (Big Endian) hinterlegt wird.</p>"}, {"id": "FIG-8db806b9828d16da", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Teilschritts „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P04mProtect()</code> des AUTOSAR E2E-Profils 4m (<code>AUTOSAR_PRS_E2EProtocol</code>). Es beschreibt die serialisierende Einbettung des Sequenzzählers in das zu übertragende Datenfeld.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext:</strong> Aufrufkontext <code>E2E_P04mProtect()</code> (gekennzeichnet über das Aktivitätsknoten-Symbol oben links).\n</li><li><strong>Zustandsstruktur / Entität:</strong> <code>State-&gt;Counter</code> (2-Byte-Zählerwert aus dem Zustandsvektor des Senders).\n</li><li><strong>Zielpuffer / Datenschnittstelle:</strong> Byte-Array <code>Data[]</code> an den Indexpositionen <code>[Offset+2...Offset+3]</code>.\n</li><li><strong>Format / Byte-Order:</strong> Big-Endian-Serialisierung (Most Significant Byte zuerst).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Pseudozustand:</strong> Start des Teilschritts „Write Counter“.\n</li><li><strong>Aktionszustand:</strong> Ausführung der Operation „Copy 2-byte State-&gt;Counter on bytes Data[Offset+2...Offset+3] in Big Endian order“. Hierbei wird der 16-Bit-Zählerwert des aktuellen Übertragungszustands big-endian in zwei aufeinanderfolgende Bytes ab Adresse <code>Offset+2</code> kopiert.\n</li><li><strong>Aktivitätsendzustand:</strong> Abschluss der Aktivität und Übergang zum nachfolgenden Schritt des E2E-Profils 4m Protect-Ablaufs.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00760]</code>. Entwickler von E2E-Profil-4m-Treibern müssen sicherstellen, dass das Feld <code>Counter</code> der Sender-Zustandsstruktur vor der Prüfsummenberechnung exakt an Offset-Position 2 und 3 im Nutzdaten-Puffer in Netzwerk-Byte-Reihenfolge (Big Endian) hinterlegt wird.</p>"}], "trans": [{"from": "FIG-194ea1174fb3e714", "to": "FIG-8db806b9828d16da", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
